// Test 1: Durum kodunun 200 OK olduğunu doğrular
pm.test("Status code is 200 OK", function() {
    pm.response.to.have.status(200);
});

//Test 2: Yanıt süresinin bir saniyeden hızlı olduğunu kontrol eder
pm.test("Response time is less than 1000ms", function(){
    pm.expect(pm.response.responseTime).to.be.below(1000);
});

// Test 3: Gelen veride sayfa numarasını doğrular
pm.test("Verify current page is 2", function(){
    var jsonData = pm.response.json();
    pm.expect(jsonData.page).to.eql(2);
});

// Test 1: Sunucunun yeni bir kaynak oluşturduğunu gösteren 201 Created kodunu doğrular
pm.test("Status code is 201 Created", function () {
    pm.response.to.have.status(201);
});

// Test 2: Gelen yanıtın içindeki ismin bizim gönderdiğimiz isimle uyuştuğunu doğrular (Data Validation)
pm.test("Verify created user name is correct", function() {
    var jsonData = pm.response.json();
    pm.expect(jsonData.name).to.eql("Junior Tester");
});
